@ The slow halves of the bus, called from the handlers' cold paths: r1 (the
@ address) kept, r0 the value read; lr = the dispatch table again on return.
@ C may clobber r0-r3, ip and lr only (AAPCS), the state is in r4-r11.
        .macro  STUB name, call, prep
        .thumb_func
\name:
        push    {r1, lr}
        \prep
        ldr     r0, [sp, #(8 + F_SA1)]
        bl      \call
        pop     {r1, r2}
        ldr     lr, [sp, #F_TAB]
        bx      r2
        .endm

        .balign 4
        STUB    sa1e_rd8_s, sa1e_read, "nop"
        STUB    sa1e_rd16_s_b0, sa1e_rd16, "add r2, r1, #1; uxth r2, r2"
        STUB    sa1e_rd16_s_l, sa1e_rd16, "add r2, r1, #1; bic r2, r2, #0xff000000"
        STUB    sa1e_rd16_s_k, sa1e_rd16, "add r2, r1, #1; uxth r2, r2; and r3, r1, #0xff0000; orr r2, r2, r3"
        STUB    sa1e_rd24_s, sa1e_rd24_b0, "nop"

@ writes: sa1e_wr8 / sa1e_wr16 / sa1e_wr16r return non-zero for a write to
@ an SA-1 register that can move the read map or raise an interrupt, or that
@ stopped a run-ahead: then r5 = 0, a resync before the next opcode. Sa1Run.wdebt gets the debt
@ the instruction started with (r11: its extra cycles come at its end), for
@ the run-ahead (sa1.c, sa1_ahead).
        .macro  WSTUB name, call, prep
        .thumb_func
\name:
        push    {r1, lr}
        ldr     ip, [sp, #(8 + F_RUN)]
        str     r11, [ip, #RUN_WDEBT]
        \prep
        ldr     r0, [sp, #(8 + F_SA1)]
        bl      \call
        cmp     r0, #0
        it      ne
        movne   r5, #0
        pop     {r1, r2}
        ldr     lr, [sp, #F_TAB]
        bx      r2
        .endm

        WSTUB   sa1e_wr8_s, sa1e_wr8, "uxtb r2, r0"
        WSTUB   sa1e_wr16_s_b0, sa1e_wr16, "uxth r3, r0; add r2, r1, #1; uxth r2, r2"
        WSTUB   sa1e_wr16_s_b0r, sa1e_wr16r, "uxth r3, r0; add r2, r1, #1; uxth r2, r2"
        WSTUB   sa1e_wr16_s_l, sa1e_wr16, "uxth r3, r0; add r2, r1, #1; bic r2, r2, #0xff000000"
        WSTUB   sa1e_wr16_s_lr, sa1e_wr16r, "uxth r3, r0; add r2, r1, #1; bic r2, r2, #0xff000000"

@ An inline I-RAM write hit a byte a run-ahead watches (WATCH): stop after
@ this instruction (Sa1Run.stop = 1, r5 = 0: the resync returns 4) with the
@ debt it started with in Sa1Run.wdebt, as the C writes do; sa1_ahead looks
@ at what changed. r0-r3 kept.
        .thumb_func
sa1e_iram_hit:
        push    {r0, r1, r2, r3, lr}
        ldr     r0, [sp, #(20 + F_RUN)]
        str     r11, [r0, #RUN_WDEBT]
        mov.w   r1, #1
        strb    r1, [r0, #RUN_STOP]
        mov.w   r5, #0
        pop     {r0, r1, r2, r3, ip}
        ldr     lr, [sp, #F_TAB]
        bx      ip

@ 24-bit writes: BW-RAM banks $40-$4F straight to the read map's page (the
@ same bytes sa1_cpu_write writes; no page during a type 1 character
@ conversion or for BW-RAM under 8 KB) and the lap marked, as the I-RAM
@ path does; the rest, or a word crossing a page, the C stubs above
        .thumb_func
sa1e_wr8_l:
        and     r3, r1, #0xf00000
        cmp     r3, #0x400000
        bne     sa1e_wr8_s
        ldr     r2, [sp, #F_SA1]
        ubfx    r3, r1, #13, #11
        ldr     r3, [r2, r3, lsl #2]
        cmp     r3, #0
        beq     sa1e_wr8_s
        ubfx    r2, r1, #0, #13
        strb    r0, [r3, r2]
        b       .Lwr_bw_done

        .macro  WR16L name, slow
        .thumb_func
\name:
        and     r3, r1, #0xf00000
        cmp     r3, #0x400000
        bne     \slow
        ubfx    r2, r1, #0, #13
        movw    r3, #0x1fff
        cmp     r2, r3
        beq     \slow
        ldr     r3, [sp, #F_SA1]
        ubfx    ip, r1, #13, #11
        ldr     r3, [r3, ip, lsl #2]
        cmp     r3, #0
        beq     \slow
        add     r3, r3, r2
        strb    r0, [r3]
        lsr     ip, r0, #8
        strb    ip, [r3, #1]
        b       .Lwr_bw_done
        .endm

        WR16L   sa1e_wr16_l, sa1e_wr16_s_l
        WR16L   sa1e_wr16_lr, sa1e_wr16_s_lr
.Lwr_bw_done:
        ldr     r2, [sp, #F_IRAM]
        str     r2, [r2, #SA1E_WDIRTY]
        mov     r2, lr
        ldr     lr, [sp, #F_TAB]
        bx      r2

